import sys,random,time,networkx as nx
sys.path.insert(0,'/workspace/submission')
import compiler
from compiler import _Gen
from networkx.algorithms.flow import dinitz,edmonds_karp,shortest_augmenting_path,preflow_push

def build(n=24,numtrees=60,seed=1):
 random.seed(seed)
 H=nx.DiGraph();H.add_nodes_from(range(n));loads={};roots={i:0 for i in range(n)}
 for k in range(numtrees):
  T=[]
  for v in range(1,n):T.append((random.randrange(v),v))
  root=random.randrange(n);w=random.randint(1,100)
  adj={i:[] for i in range(n)}
  for a,b in T:adj[a].append(b);adj[b].append(a)
  st=[root];seen={root}
  while st:
   x=st.pop()
   for y in adj[x]:
    if y not in seen:seen.add(y);loads[(x,y)]=loads.get((x,y),0)+w;st.append(y)
  roots[root]+=w
 for (a,b),c in loads.items():H.add_edge(a,b,capacity=c)
 return H,roots

def run(algo):
 H,roots=build()
 orig=compiler.nx.maximum_flow_value
 calls=[0]
 def mf(G,s,t):
  calls[0]+=1
  return algo(G,s,t,value_only=True)
 compiler.nx.maximum_flow_value=mf
 t=time.time()
 try:
  Ts,Cs=_Gen(H,list(range(24)),roots).generate()
  print(algo.__name__,'time',time.time()-t,'calls',calls[0],'trees',len(Ts))
 finally:compiler.nx.maximum_flow_value=orig
for algo in [dinitz,edmonds_karp,shortest_augmenting_path,preflow_push]:
 run(algo)
PY
